import { useRef } from 'react';
import { ReproductionControl } from './control-labels.ts';
import './control.css';
import './reproduction.css';

const BOARD_CODE_MAX_CHARACTERS = 32;
interface BoardCodeFormProps {
  code: string;
  generation: number;
  loadBoard(code: string): boolean;
}

export function BoardCodeForm({ code, generation, loadBoard }: BoardCodeFormProps) {
  const loadButton = useRef<HTMLButtonElement>(null);
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        const draft = new FormData(event.currentTarget).get('boardCode');
        // A loaded deal replaces the input, so focus moves to Load board. An invalid code
        // keeps focus in the draft for correction.
        if (typeof draft === 'string' && loadBoard(draft)) loadButton.current?.focus();
      }}
    >
      <label htmlFor="board-code">{ReproductionControl.board}</label>
      <div className="control-row">
        <input
          key={generation}
          id="board-code"
          className="control"
          name="boardCode"
          defaultValue={code}
          maxLength={BOARD_CODE_MAX_CHARACTERS}
          spellCheck={false}
          autoComplete="off"
        />
        <button ref={loadButton} type="submit" className="control" aria-describedby="load-notice">
          {ReproductionControl.loadBoard}
        </button>
      </div>
    </form>
  );
}
import { GRID_SIZES } from '../deck.ts';
import { DealControl } from './control-labels.ts';
import './control.css';
import './controls.css';

interface ControlsProps {
  size: number;
  newGame(size?: number): void;
  restart(): void;
}

export function Controls({ size, newGame, restart }: ControlsProps) {
  return (
    <div className="controls">
      <div className="size-control">
        <label htmlFor="grid-size">{DealControl.size}</label>
        <select
          id="grid-size"
          className="control"
          value={size}
          onChange={(event) => newGame(Number(event.currentTarget.value))}
        >
          {GRID_SIZES.map((option) => (
            <option key={option} value={option}>
              {option}x{option}
            </option>
          ))}
        </select>
      </div>
      <button type="button" className="control" onClick={() => newGame()}>
        {DealControl.newGame}
      </button>
      <button type="button" className="control" onClick={restart}>
        {DealControl.restart}
      </button>
    </div>
  );
}
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { GRID_SIZES } from '../src/game/deck.ts';
import { SessionNotice } from '../src/game/session/session.ts';
import { loadTimedBoard, exportedSnapshot, GAME_URL } from './game-fixture.ts';

// The published input limits, kept apart from the components that set them.
const BOARD_CODE_MAX_CHARACTERS = 32;
const SNAPSHOT_MAX_CHARACTERS = 65_536;

test('native reproduction controls keep drafts, limits, exact errors and action focus', async ({
  page,
}) => {
  await page.goto(GAME_URL);
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await expect(page.locator('summary')).toHaveText(ReproductionControl.summary);
  const options = await page
    .getByLabel(DealControl.size, { exact: true })
    .locator('option')
    .evaluateAll((items) =>
      items.map((item) => {
        if (!(item instanceof HTMLOptionElement)) throw new Error('Expected a native option.');
        return { value: item.value, text: item.textContent };
      }),
    );
  expect(options).toEqual(
    GRID_SIZES.map((size) => ({ value: String(size), text: `${size}x${size}` })),
  );
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const code = page.getByLabel(ReproductionControl.board, { exact: true });
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  await expect(code).toHaveAttribute('maxlength', String(BOARD_CODE_MAX_CHARACTERS));
  await expect(field).toHaveAttribute('maxlength', String(SNAPSHOT_MAX_CHARACTERS));
  await code.fill('draft');
  await page.locator('.card').first().click();
  expect(await code.inputValue()).toBe('draft');
  const load = page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true });
  await load.click();
  await expect(load).toBeFocused();
  await expect(page.locator('.load-notice')).toHaveText(SessionNotice.invalidBoard);
  await field.fill('{');
  const importButton = page.getByRole('button', {
    name: ReproductionControl.loadSnapshot,
    exact: true,
  });
  await importButton.click();
  await expect(importButton).toBeFocused();
  await expect(page.locator('.load-notice')).toHaveText(SessionNotice.invalidSnapshot);
  const exportButton = page.getByRole('button', {
    name: ReproductionControl.exportSnapshot,
    exact: true,
  });
  await exportButton.click();
  await expect(exportButton).toBeFocused();
  const text = await field.inputValue();
  expect(text).toContain('\n');
  await field.selectText();
  expect(
    await field.evaluate((element) => {
      if (!(element instanceof HTMLTextAreaElement)) throw new Error('Expected a textarea.');
      return element.selectionEnd - element.selectionStart;
    }),
  ).toBe(text.length);
  await code.fill(EXAMPLE_CODE);
  await load.click();
  await expect(load).toBeFocused();
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({ moves: 0, elapsedMs: 0, started: false });
});
import { expect } from '@playwright/test';
import { test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import { loadTimedBoard, moves } from './game-fixture.ts';

test('native Tab remembers board focus and matched cards stay focusable and inactive', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).focus();
  await page.keyboard.press('Shift+Tab');
  await expect(page.getByRole('button', { name: DealControl.restart, exact: true })).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(cards.nth(5)).toBeFocused();
  await page.keyboard.press('ArrowLeft');
  await page.keyboard.press('Space');
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('Enter');
  await expect(page.locator('.card.matched')).toHaveCount(2);
  await expect(cards.nth(5)).toHaveAttribute('aria-disabled', 'true');
  await expect(cards.nth(5)).toBeFocused();
  await page.keyboard.press('Space');
  expect(await moves(page)).toBe(1);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
});

test('Alt+ArrowLeft and Ctrl+End stay with the browser and leave the board alone', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const card = page.locator('.card').nth(5);
  await card.focus();
  const url = page.url();
  for (const key of ['Alt+ArrowLeft', 'Control+End']) {
    await page.keyboard.press(key);
    await expect(card, `I06 ${key} keeps focus`).toBeFocused();
    await expect(page.locator('.card.revealed'), `I06 ${key} reveals no card`).toHaveCount(0);
  }
  expect(await moves(page)).toBe(0);
  expect(page.url()).toBe(url);
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { StatusLabel } from '../src/game/status/status-labels.ts';
import { loadTimedBoard } from './game-fixture.ts';
import { uiSnapshot } from './ui-snapshot.ts';

test('completion shows final moves and time and keeps the completed clock stopped', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const expected = await uiSnapshot();
  await expect(page.locator('.stats dd').nth(3)).toHaveText(expected.bestNone);
  const firstPair = EXAMPLE_PAIRS[0];
  await page.locator('.card').nth(firstPair[0]).click();
  await page.clock.runFor(3000);
  await page.locator('.card').nth(firstPair[1]).click();
  for (const pair of EXAMPLE_PAIRS.slice(1))
    for (const index of pair) await page.locator('.card').nth(index).click();
  const banner = page.locator('.victory');
  await expect(banner).toHaveText(expected.winBanner);
  await expect(banner, 'V06 banner text').toHaveCSS('color', 'rgb(244, 246, 255)');
  await expect(banner, 'V06 banner border').toHaveCSS('border-color', 'rgb(117, 124, 154)');
  await expect(page.getByRole('status')).toHaveText(expected.winningResult);
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(EXAMPLE_PAIRS.length);
  const elapsed = await page
    .locator('.stats > div')
    .filter({ has: page.getByText(StatusLabel.time, { exact: true }) })
    .locator('dd')
    .textContent();
  await page.clock.runFor(5000);
  expect(
    await page
      .locator('.stats > div')
      .filter({ has: page.getByText(StatusLabel.time, { exact: true }) })
      .locator('dd')
      .textContent(),
  ).toBe(elapsed);
});

